package com.docuflow.service;
import com.docuflow.dto.AuthDtos.*; import com.docuflow.entity.User; import com.docuflow.exception.ApiException; import com.docuflow.repository.UserRepository; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class UserManagementService { private final UserRepository users; private final PasswordEncoder encoder; public UserManagementService(UserRepository users,PasswordEncoder encoder){this.users=users;this.encoder=encoder;} public UserResponse create(CreateUserRequest request){if(users.existsByEmailIgnoreCase(request.email()))throw new ApiException(HttpStatus.CONFLICT,"A user with this email already exists");User u=users.save(new User(request.fullName().trim(),request.email().trim().toLowerCase(),encoder.encode(request.password()),request.role()));return new UserResponse(u.getId(),u.getFullName(),u.getEmail(),u.getRole());} }
